# tkinter tutorial Programfrom tkinter import *class win(Frame):    def __init__(self, master = None):        Frame.__init__(self,master)        self.master = master        self.init_window()            def init_window(self):        self.master.title("GUI")        self.pack(fill=BOTH, expand=1)        but1 = Button(self, text = 'Browse')        but1.place(x=70, y=30)       root = Tk() root.geometry('400x300')app = win(root)root.mainloop()